implementation:
#include <stdlib.h>
#include <string.h>
#include <krb5/krb5.h>

krb5_int32 find_referral_tgs(kdc_realm_t *kdc_active_realm, krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = KRB5KDC_ERR_GENERIC;
    krb5_data *hostname = NULL;
    krb5_realm *target_realm = NULL;

    if (!kdc_active_realm || !request || !krbtgt_princ) {
        return KRB5KDC_ERR_BADOPTION;
    }

    if (!request->server) {
        return KRB5KDC_ERR_BAD_SERVER;
    }

    /* Extract hostname from server principal */
    ret = krb5_unparse_name(kdc_active_realm->context, request->server, &hostname);
    if (ret != 0) {
        return ret;
    }

    /* Check if the hostname is a valid FQDN */
    if (!hostname || hostname->length == 0) {
        krb5_free_data(kdc_active_realm->context, hostname);
        return KRB5KDC_ERR_BAD_FQDN;
    }

    /* Find the realm associated with the hostname */
    target_realm = kdc_find_realm_by_hostname(kdc_active_realm, hostname->data);
    if (!target_realm) {
        krb5_free_data(kdc_active_realm->context, hostname);
        return KRB5KDC_ERR_NO_REALM;
    }

    /* Ensure the realm is valid and not empty */
    if (target_realm->realm.length == 0) {
        krb5_free_data(kdc_active_realm->context, hostname);
        return KRB5KDC_ERR_BAD_REALM;
    }

    /* Construct the TGT principal for the referral realm */
    ret = krb5_build_principal(kdc_active_realm->context, krbtgt_princ, target_realm->realm.length, target_realm->realm.data, 5, "krbtgt", target_realm->realm.length, target_realm->realm.data, NULL);
    if (ret != 0) {
        krb5_free_data(kdc_active_realm->context, hostname);
        return ret;
    }

    /* Clean up allocated resources */
    krb5_free_data(kdc_active_realm->context, hostname);

    return 0; /* Success */
}
